[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>RedRoom Fitness — The Best HIIT Workout in the World</title>
  <meta name="title" content="RedRoom Fitness — The Best HIIT Workout in the World">
  <meta name="description" content="The world's best HIIT workout. Treadmill running + strength training in a signature red-lit studio. Book your first class or stream on demand. Try free for 30 days.">
  <link rel="canonical" href="https://www.redroom.com/">
  <meta property="og:type" content="website">
  <meta property="og:url" content="https://www.redroom.com/">
  <meta property="og:title" content="RedRoom Fitness — The Best HIIT Workout in the World">
  <meta property="og:description" content="The world's best HIIT workout. Treadmill running + strength training in a signature red-lit studio. Book your first class or stream on demand.">
  <meta property="og:image" content="https://www.redroom.com/og-image.jpg">
  <meta property="twitter:card" content="summary_large_image">
  <meta property="twitter:url" content="https://www.redroom.com/">
  <meta property="twitter:title" content="RedRoom Fitness — The Best HIIT Workout in the World">
  <meta property="twitter:description" content="The world's best HIIT workout. Treadmill running + strength training in a signature red-lit studio.">
  <meta property="twitter:image" content="https://www.redroom.com/og-image.jpg">
  <script type="application/ld+json">
  {
    "@context": "https://schema.org",
    "@type": "SportsActivityLocation",
    "name": "RedRoom Fitness",
    "image": "https://www.redroom.com/og-image.jpg",
    "description": "The original high-intensity interval training experience combining treadmill running and strength training in a signature red-lit studio environment.",
    "@id": "https://www.redroom.com/#organization",
    "url": "https://www.redroom.com",
    "telephone": "+1-800-REDROOM",
    "priceRange": "$$",
    "sameAs": [
      "https://www.instagram.com/redroomfitness",
      "https://www.facebook.com/redroomfitness"
    ],
    "areaServed": [
      { "@type": "City", "name": "New York" },
      { "@type": "City", "name": "Los Angeles" },
      { "@type": "City", "name": "London" },
      { "@type": "City", "name": "Miami" },
      { "@type": "City", "name": "San Francisco" }
    ]
  }
  </script>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Inter:wght@300;400;500;600&display=swap" rel="stylesheet">
  <link rel="stylesheet" href="shared.css">
  <style>
    /* ===== HERO ===== */
    .hero {
      position: relative;
      min-height: 100vh;
      display: flex;
      align-items: center;
      justify-content: center;
      text-align: center;
      overflow: hidden;
      background: #141414;
    }
    .hero-bg {
      position: absolute;
      inset: 0;
      background: radial-gradient(ellipse at 50% 60%, rgba(255,0,0,0.18) 0%, transparent 70%),
                  linear-gradient(180deg, #141414 0%, #0a0a0a 100%);
    }
    .hero-content {
      position: relative;
      z-index: 2;
      max-width: 900px;
      padding: 0 2rem;
    }
    .hero-eyebrow {
      font-family: 'Oswald', sans-serif;
      font-size: 0.85rem;
      letter-spacing: 0.25em;
      color: #FF0000;
      text-transform: uppercase;
      margin-bottom: 1.5rem;
    }
    .hero-title {
      font-family: 'Oswald', sans-serif;
      font-size: clamp(3rem, 8vw, 7rem);
      font-weight: 700;
      line-height: 0.95;
      text-transform: uppercase;
      color: #fff;
      margin-bottom: 1.5rem;
    }
    .hero-title span { color: #FF0000; }
    .hero-sub {
      font-family: 'Inter', sans-serif;
      font-size: clamp(1rem, 2vw, 1.2rem);
      color: rgba(255,255,255,0.7);
      max-width: 600px;
      margin: 0 auto 2.5rem;
      line-height: 1.6;
    }
    .hero-cta {
      display: flex;
      gap: 1rem;
      justify-content: center;
      flex-wrap: wrap;
    }

    /* ===== COMMUNITY PROMO ===== */
    .community {
      background: #1a1a1a;
      padding: 6rem 2rem;
      text-align: center;
    }
    .community .section-label {
      color: #FF0000;
      font-family: 'Oswald', sans-serif;
      font-size: 0.8rem;
      letter-spacing: 0.3em;
      text-transform: uppercase;
      margin-bottom: 1.5rem;
    }
    .community h2 {
      font-family: 'Oswald', sans-serif;
      font-size: clamp(2.5rem, 5vw, 4rem);
      font-weight: 700;
      text-transform: uppercase;
      color: #fff;
      margin-bottom: 2rem;
    }
    .community p {
      font-family: 'Inter', sans-serif;
      color: rgba(255,255,255,0.65);
      font-size: 1.1rem;
      line-height: 1.8;
      max-width: 680px;
      margin: 0 auto 2.5rem;
    }

    /* ===== TWO WAYS ===== */
    .two-ways {
      padding: 6rem 2rem;
      background: #141414;
    }
    .two-ways-inner {
      max-width: 1200px;
      margin: 0 auto;
    }
    .two-ways h2 {
      font-family: 'Oswald', sans-serif;
      font-size: clamp(2rem, 4vw, 3.5rem);
      font-weight: 700;
      text-transform: uppercase;
      color: #fff;
      text-align: center;
      margin-bottom: 4rem;
    }
    .two-ways-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 2px;
    }
    .way-card {
      position: relative;
      padding: 4rem 3rem;
      background: #1a1a1a;
      overflow: hidden;
      transition: background 0.3s;
    }
    .way-card:hover { background: #1f1f1f; }
    .way-card::before {
      content: '';
      position: absolute;
      top: 0; left: 0;
      width: 4px;
      height: 100%;
      background: #FF0000;
    }
    .way-card .way-icon {
      font-size: 2.5rem;
      margin-bottom: 1.5rem;
    }
    .way-card h3 {
      font-family: 'Oswald', sans-serif;
      font-size: 2rem;
      font-weight: 700;
      text-transform: uppercase;
      color: #fff;
      margin-bottom: 1rem;
    }
    .way-card p {
      font-family: 'Inter', sans-serif;
      color: rgba(255,255,255,0.6);
      line-height: 1.7;
      font-size: 1rem;
    }
    .way-tag {
      display: inline-block;
      background: #FF0000;
      color: #fff;
      font-family: 'Oswald', sans-serif;
      font-size: 0.75rem;
      letter-spacing: 0.2em;
      text-transform: uppercase;
      padding: 0.3rem 0.8rem;
      margin-bottom: 1rem;
    }

    /* ===== STUDIO EXPERIENCE ===== */
    .studio-exp {
      background: #0d0d0d;
      padding: 8rem 2rem;
      text-align: center;
      position: relative;
      overflow: hidden;
    }
    .studio-exp::before {
      content: '';
      position: absolute;
      inset: 0;
      background: radial-gradient(ellipse at 50% 50%, rgba(255,0,0,0.12) 0%, transparent 65%);
      pointer-events: none;
    }
    .studio-exp-inner {
      position: relative;
      z-index: 2;
      max-width: 800px;
      margin: 0 auto;
    }
    .studio-exp h2 {
      font-family: 'Oswald', sans-serif;
      font-size: clamp(2.5rem, 5vw, 5rem);
      font-weight: 700;
      text-transform: uppercase;
      color: #fff;
      line-height: 1;
      margin-bottom: 2rem;
    }
    .studio-exp p {
      font-family: 'Inter', sans-serif;
      color: rgba(255,255,255,0.65);
      font-size: 1.15rem;
      line-height: 1.8;
      margin-bottom: 3rem;
    }
    .studio-stats {
      display: flex;
      justify-content: center;
      gap: 4rem;
      margin-bottom: 3rem;
      flex-wrap: wrap;
    }
    .studio-stat .num {
      font-family: 'Oswald', sans-serif;
      font-size: 3rem;
      font-weight: 700;
      color: #FF0000;
      line-height: 1;
    }
    .studio-stat .label {
      font-family: 'Inter', sans-serif;
      color: rgba(255,255,255,0.5);
      font-size: 0.85rem;
      letter-spacing: 0.15em;
      text-transform: uppercase;
      margin-top: 0.5rem;
    }

    /* ===== FREE TRIAL CTA ===== */
    .free-trial {
      background: #FF0000;
      padding: 6rem 2rem;
      text-align: center;
    }
    .free-trial h2 {
      font-family: 'Oswald', sans-serif;
      font-size: clamp(2.5rem, 5vw, 4.5rem);
      font-weight: 700;
      text-transform: uppercase;
      color: #fff;
      margin-bottom: 2rem;
      line-height: 1.05;
    }
    .free-trial .btn-white {
      background: #fff;
      color: #FF0000;
      font-family: 'Oswald', sans-serif;
      font-weight: 700;
      font-size: 1.1rem;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      padding: 1.1rem 3rem;
      border: none;
      cursor: pointer;
      text-decoration: none;
      display: inline-block;
      transition: transform 0.2s, box-shadow 0.2s;
    }
    .free-trial .btn-white:hover {
      transform: translateY(-2px);
      box-shadow: 0 8px 30px rgba(0,0,0,0.3);
    }

    /* ===== CAROUSEL ===== */
    .carousel-section {
      background: #141414;
      padding: 5rem 0;
      overflow: hidden;
    }
    .carousel-section h2 {
      font-family: 'Oswald', sans-serif;
      font-size: 2.5rem;
      font-weight: 700;
      text-transform: uppercase;
      color: #fff;
      text-align: center;
      margin-bottom: 3rem;
      padding: 0 2rem;
    }
    .carousel-wrapper {
      position: relative;
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 4rem;
    }
    .carousel-track-container {
      overflow: hidden;
      border-radius: 2px;
    }
    .carousel-track {
      display: flex;
      transition: transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    }
    .carousel-slide {
      min-width: 33.333%;
      padding: 0 0.5rem;
    }
    .carousel-card {
      height: 380px;
      background: #1e1e1e;
      position: relative;
      overflow: hidden;
      display: flex;
      align-items: flex-end;
    }
    .carousel-card-bg {
      position: absolute;
      inset: 0;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 5rem;
    }
    .carousel-card-overlay {
      position: absolute;
      inset: 0;
      background: linear-gradient(to top, rgba(0,0,0,0.85) 0%, transparent 60%);
    }
    .carousel-card-content {
      position: relative;
      z-index: 2;
      padding: 2rem;
    }
    .carousel-card-content h3 {
      font-family: 'Oswald', sans-serif;
      font-size: 1.3rem;
      font-weight: 600;
      text-transform: uppercase;
      color: #fff;
      margin-bottom: 0.3rem;
    }
    .carousel-card-content p {
      font-family: 'Inter', sans-serif;
      color: rgba(255,255,255,0.6);
      font-size: 0.85rem;
    }
    .carousel-btn {
      position: absolute;
      top: 50%;
      transform: translateY(-50%);
      width: 48px;
      height: 48px;
      background: #FF0000;
      border: none;
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
      z-index: 10;
      transition: background 0.2s;
    }
    .carousel-btn:hover { background: #cc0000; }
    .carousel-btn svg { width: 20px; height: 20px; fill: #fff; }
    .carousel-btn.prev { left: 0; }
    .carousel-btn.next { right: 0; }
    .carousel-dots {
      display: flex;
      justify-content: center;
      gap: 0.5rem;
      margin-top: 2rem;
    }
    .carousel-dot {
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: rgba(255,255,255,0.2);
      border: none;
      cursor: pointer;
      padding: 0;
      transition: background 0.2s;
    }
    .carousel-dot.active { background: #FF0000; }

    /* ===== NEWSLETTER ===== */
    .newsletter {
      background: #1a1a1a;
      padding: 5rem 2rem;
      text-align: center;
    }
    .newsletter h2 {
      font-family: 'Oswald', sans-serif;
      font-size: clamp(1.8rem, 3vw, 2.5rem);
      font-weight: 700;
      text-transform: uppercase;
      color: #fff;
      margin-bottom: 0.75rem;
    }
    .newsletter p {
      font-family: 'Inter', sans-serif;
      color: rgba(255,255,255,0.55);
      margin-bottom: 2rem;
      font-size: 1rem;
    }
    .newsletter-form {
      display: flex;
      max-width: 480px;
      margin: 0 auto;
      gap: 0;
    }
    .newsletter-form input[type="email"] {
      flex: 1;
      background: #111;
      border: 1px solid #333;
      border-right: none;
      color: #fff;
      font-family: 'Inter', sans-serif;
      font-size: 0.95rem;
      padding: 0.85rem 1.25rem;
      outline: none;
      transition: border-color 0.2s;
    }
    .newsletter-form input[type="email"]:focus { border-color: #FF0000; }
    .newsletter-form input[type="email"].error { border-color: #ff4444; }
    .newsletter-form button {
      background: #FF0000;
      color: #fff;
      border: none;
      font-family: 'Oswald', sans-serif;
      font-weight: 600;
      font-size: 0.9rem;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      padding: 0.85rem 1.75rem;
      cursor: pointer;
      transition: background 0.2s;
    }
    .newsletter-form button:hover { background: #cc0000; }
    .newsletter-msg {
      margin-top: 0.75rem;
      font-family: 'Inter', sans-serif;
      font-size: 0.9rem;
      min-height: 1.2em;
    }
    .newsletter-msg.success { color: #4caf50; }
    .newsletter-msg.error { color: #ff4444; }

    @media (max-width: 768px) {
      .two-ways-grid { grid-template-columns: 1fr; }
      .carousel-slide { min-width: 85%; }
      .carousel-wrapper { padding: 0 3rem; }
    }
  </style>
</head>
<body>

  <!-- TOP BAR -->
  <div class="topbar">
    <span>The Best (Digital) Workout in the World</span>
    <a href="digital-platform.html" class="topbar-cta">Learn More →</a>
  </div>

  <!-- NAV -->
  <nav class="nav">
    <a href="index.html" class="nav-logo">RED<span>ROOM</span></a>
