    <div class="nav-ctas">
      <a href="#free-trial" class="btn btn-outline">Book Now</a>
      <a href="#free-trial" class="btn btn-red">Buy Classes</a>
    </div>
  </nav>

  <!-- HERO -->
  <section class="hero">
    <div class="hero-bg"></div>
    <div class="hero-content">
      <p class="hero-eyebrow">The Original HIIT Experience</p>
      <h1 class="hero-title">TRY THE BEST<br>WORKOUT IN<br>THE <span>WORLD™</span></h1>
      <p class="hero-sub">Buy an exclusive first-timer 3-pack and receive a FREE Fuel Shake or Grab + Go item after your third class.</p>
      <div class="hero-cta">
        <a href="#free-trial" class="btn btn-red btn-lg">BUY NOW</a>
        <a href="the-workout.html" class="btn btn-outline btn-lg">BOOK CLASSES</a>
      </div>
    </div>
    <div class="hero-scroll">
      <span>Scroll</span>
      <div class="hero-scroll-line"></div>
    </div>
  </section>

  <!-- COMMUNITY PROMO -->
  <section class="community">
    <div class="section-label">RedRoom Community</div>
    <h2>Join the Hustle</h2>
    <p>Welcome to RedRoom. More than a workout — it's a movement. Our global community of athletes, first-timers, and everyone in between push limits together in the Red Room. Show up. Work hard. Earn your place.</p>
    <a href="instructors.html" class="btn btn-outline">Explore the Community</a>
  </section>

  <!-- TWO WAYS -->
