    <div class="two-ways-inner">
      <h2>Two Ways to Red Room</h2>
      <div class="two-ways-grid">
        <div class="way-card">
          <div class="way-tag">In-Studio</div>
          <div class="way-icon">🔴</div>
          <h3>Get a (Red) Room</h3>
          <p>Step inside our signature red-lit studios for the full immersive experience. Heart-pounding music, elite instructors, and the energy of the pack.</p>
          <a href="the-workout.html" class="btn btn-red" style="margin-top:2rem;">Book a Class</a>
        </div>
        <div class="way-card">
          <div class="way-tag">Digital</div>
          <div class="way-icon">📱</div>
          <h3>Go Digital</h3>
          <p>Stream world-class workouts from anywhere. Same intensity, your schedule. Access the full RedRoom library on demand.</p>
          <a href="digital-platform.html" class="btn btn-red" style="margin-top:2rem;">Start Streaming</a>
        </div>
      </div>
    </div>
  </section>

  <!-- STUDIO EXPERIENCE -->
  <section class="studio-exp">
    <div class="studio-exp-inner">
      <h2>Meet Us in the Red Room.</h2>
      <p>Red lights. Loud music. Zero distractions. Our studios are purpose-built for performance — every detail from the sound system to the lighting is engineered to push you harder. This isn't a gym. This is the Red Room.</p>
      <div class="studio-stats">
        <div class="studio-stat"><div class="num">50</div><div class="label">Min Classes</div></div>
        <div class="studio-stat"><div class="num">5+</div><div class="label">Global Cities</div></div>
        <div class="studio-stat"><div class="num">100%</div><div class="label">Full Body</div></div>
      </div>
      <a href="the-workout.html" class="btn btn-red btn-lg">Book Now</a>
    </div>
  </section>

  <!-- FREE TRIAL CTA -->
  <section id="free-trial" class="free-trial">
    <h2>Join Us for a<br>Free 30 Day Trial</h2>
    <a href="digital-platform.html" class="btn-white">Start Your Free Trial</a>
  </section>

  <!-- LIFESTYLE CAROUSEL -->
  <section class="carousel-section">
    <h2>The RedRoom Life</h2>
    <div class="carousel-wrapper">
      <button class="carousel-btn prev" aria-label="Previous slide">
        <svg viewBox="0 0 24 24"><path d="M15 18l-6-6 6-6"/></svg>
      </button>
      <div class="carousel-track-container">
        <div class="carousel-track" id="carouselTrack">
          <div class="carousel-slide">
            <div class="carousel-card">
              <div class="carousel-card-bg" style="background:linear-gradient(135deg,#1a0000,#330000)">🏃</div>
              <div class="carousel-card-overlay"></div>
              <div class="carousel-card-content"><h3>Treadmill Sessions</h3><p>Coach-led intervals</p></div>
            </div>
          </div>
          <div class="carousel-slide">
            <div class="carousel-card">
              <div class="carousel-card-bg" style="background:linear-gradient(135deg,#0a0a1a,#1a0a2e)">💪</div>
              <div class="carousel-card-overlay"></div>
              <div class="carousel-card-content"><h3>Floor Training</h3><p>Strength meets results</p></div>
            </div>
          </div>
          <div class="carousel-slide">
            <div class="carousel-card">
              <div class="carousel-card-bg" style="background:linear-gradient(135deg,#1a1000,#2a1a00)">🔴</div>
              <div class="carousel-card-overlay"></div>
              <div class="carousel-card-content"><h3>The Red Room</h3><p>Immersive studio energy</p></div>
            </div>
          </div>
          <div class="carousel-slide">
            <div class="carousel-card">
              <div class="carousel-card-bg" style="background:linear-gradient(135deg,#001a0a,#002a14)">🤝</div>
              <div class="carousel-card-overlay"></div>
              <div class="carousel-card-content"><h3>Community Events</h3><p>Beyond the workout</p></div>
            </div>
          </div>
          <div class="carousel-slide">
            <div class="carousel-card">
              <div class="carousel-card-bg" style="background:linear-gradient(135deg,#1a0010,#2a001a)">👕</div>
              <div class="carousel-card-overlay"></div>
              <div class="carousel-card-content"><h3>RedRoom Apparel</h3><p>Wear the movement</p></div>
