          </ul>
        </div>
        <div class="footer-col">
          <h4>Connect</h4>
          <ul>
            <li><a href="#">Shop</a></li>
            <li><a href="#">My Account</a></li>
            <li><a href="#">Download App (iOS)</a></li>
            <li><a href="#">Download App (Android)</a></li>
          </ul>
        </div>
        <div class="footer-col">
          <h4>Region</h4>
          <div class="country-selector-wrapper">
            <button class="country-selector-btn" id="countrySelectorBtn" aria-expanded="false">
              🌐 United States
              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M6 9l6 6 6-6"/></svg>
            </button>
            <div class="country-dropdown" id="countryDropdown" hidden>
              <a href="#" class="country-option active">🇺🇸 United States</a>
              <a href="#" class="country-option">🇬🇧 United Kingdom</a>
              <a href="#" class="country-option">🇦🇺 Australia</a>
              <a href="#" class="country-option">🇨🇦 Canada</a>
              <a href="#" class="country-option">🇩🇪 Germany</a>
              <a href="#" class="country-option">🇫🇷 France</a>
            </div>
          </div>
        </div>
      </div>
      <div class="footer-bottom">
        <p>© 2026 RedRoom Fitness. All rights reserved.</p>
        <div class="footer-legal">
          <a href="#">Privacy Policy</a>
          <a href="#">Terms of Service</a>
          <a href="#">Cookie Policy</a>
        </div>
      </div>
    </div>
