/* ===== SHARED CSS — RedRoom Fitness ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --red: #FF0000;
  --bg: #141414;
  --surface: #1a1a1a;
  --text: #fff;
  --muted: rgba(255,255,255,0.6);
}

html { scroll-behavior: smooth; }

body {
  background: #141414;
  color: #fff;
  font-family: 'Inter', Helvetica Neue, Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

a { color: inherit; text-decoration: none; }

/* ===== TOPBAR ===== */
.topbar {
  background: #FF0000;
  text-align: center;
  padding: 0.6rem 1rem;
  font-family: 'Inter', sans-serif;
  font-size: 0.85rem;
  font-weight: 500;
  letter-spacing: 0.04em;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  color: #fff;
}
.topbar-cta {
  font-weight: 700;
  text-decoration: underline;
  color: #fff;
}

/* ===== NAV ===== */
.nav {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(20,20,20,0.97);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(255,255,255,0.06);
  display: flex;
  align-items: center;
  padding: 0 2rem;
  height: 68px;
  gap: 2rem;
}
.nav-logo {
  font-family: 'Oswald', sans-serif;
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  color: #fff;
  flex-shrink: 0;
}
.nav-logo span { color: #FF0000; }
.nav-links {
  display: flex;
  list-style: none;
  gap: 0.25rem;
  flex: 1;
}
.nav-links a {
  font-family: 'Oswald', sans-serif;
  font-size: 0.85rem;
  font-weight: 500;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.7);
  padding: 0.5rem 0.75rem;
  transition: color 0.2s;
  display: block;
}
.nav-links a:hover,
.nav-links a.active { color: #FF0000; }
.nav-ctas {
  display: flex;
  gap: 0.75rem;
  flex-shrink: 0;
}
.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0.5rem;
  margin-left: auto;
}
.nav-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: #fff;
  transition: 0.3s;
}

/* ===== BUTTONS ===== */
.btn {
  display: inline-block;
  font-family: 'Oswald', sans-serif;
  font-weight: 600;
  font-size: 0.85rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 0.65rem 1.5rem;
  border: 2px solid transparent;
  cursor: pointer;
  transition: background 0.2s, color 0.2s, border-color 0.2s, transform 0.15s;
  white-space: nowrap;
}
.btn:hover { transform: translateY(-1px); }
.btn-red {
  background: #FF0000;
  color: #fff;
  border-color: #FF0000;
}
.btn-red:hover { background: #cc0000; border-color: #cc0000; }
.btn-outline {
  background: transparent;
  color: #fff;
  border-color: rgba(255,255,255,0.4);
}
.btn-outline:hover { border-color: #FF0000; color: #FF0000; }
.btn-lg {
  font-size: 1rem;
  padding: 1rem 2.5rem;
  letter-spacing: 0.15em;
}

/* ===== PAGE HERO (inner pages) ===== */
.page-hero {
  background: #0d0d0d;
  padding: 7rem 2rem 5rem;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.page-hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 50% 100%, rgba(255,0,0,0.15) 0%, transparent 60%);
  pointer-events: none;
}
.page-hero-inner {
  position: relative;
  z-index: 2;
  max-width: 800px;
  margin: 0 auto;
}
.page-hero .eyebrow {
  font-family: 'Oswald', sans-serif;
  font-size: 0.8rem;
  letter-spacing: 0.3em;
  color: #FF0000;
  text-transform: uppercase;
  margin-bottom: 1.25rem;
}
.page-hero h1 {
  font-family: 'Oswald', sans-serif;
  font-size: clamp(2.5rem, 6vw, 5.5rem);
  font-weight: 700;
  text-transform: uppercase;
  line-height: 0.95;
  color: #fff;
  margin-bottom: 1.5rem;
}
.page-hero h1 span { color: #FF0000; }
.page-hero p {
  font-family: 'Inter', sans-serif;
  font-size: 1.1rem;
  color: rgba(255,255,255,0.65);
  line-height: 1.7;
  max-width: 580px;
  margin: 0 auto 2rem;
}

/* ===== HERO SCROLL INDICATOR ===== */
.hero-scroll {
  position: absolute;
  bottom: 2rem;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5rem;
  opacity: 0.4;
  z-index: 3;
}
.hero-scroll span {
  font-family: 'Oswald', sans-serif;
  font-size: 0.7rem;
  letter-spacing: 0.3em;
  text-transform: uppercase;
}
.hero-scroll-line {
  width: 1px;
  height: 40px;
  background: linear-gradient(to bottom, #fff, transparent);
  animation: scrollLine 1.5s ease-in-out infinite;
}
@keyframes scrollLine {
  0% { transform: scaleY(0); transform-origin: top; }
  50% { transform: scaleY(1); transform-origin: top; }
  50.01% { transform-origin: bottom; }
  100% { transform: scaleY(0); transform-origin: bottom; }
}

/* ===== SECTION UTILITIES ===== */
.section-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 2rem;
}
.section-header {
  text-align: center;
  margin-bottom: 4rem;
}
.section-header .eyebrow {
  font-family: 'Oswald', sans-serif;
  font-size: 0.8rem;
  letter-spacing: 0.3em;
  color: #FF0000;
  text-transform: uppercase;
  margin-bottom: 1rem;
  display: block;
}
.section-header h2 {
  font-family: 'Oswald', sans-serif;
  font-size: clamp(2rem, 4vw, 3.5rem);
  font-weight: 700;
  text-transform: uppercase;
  color: #fff;
  line-height: 1;
}
.section-header p {
  font-family: 'Inter', sans-serif;
  color: rgba(255,255,255,0.6);
  font-size: 1.05rem;
  line-height: 1.7;
  max-width: 580px;
  margin: 1.5rem auto 0;
}

/* ===== FOOTER ===== */
.footer {
  background: #0d0d0d;
  border-top: 1px solid rgba(255,255,255,0.06);
  padding: 5rem 2rem 2rem;
}
.footer-inner { max-width: 1200px; margin: 0 auto; }
.footer-logo {
  font-family: 'Oswald', sans-serif;
  font-size: 2rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  margin-bottom: 3rem;
}
.footer-logo span { color: #FF0000; }
.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 3rem;
  margin-bottom: 3rem;
}
.footer-col h4 {
  font-family: 'Oswald', sans-serif;
  font-size: 0.8rem;
  letter-spacing: 0.25em;
  text-transform: uppercase;
  color: #FF0000;
  margin-bottom: 1.25rem;
}
.footer-col ul { list-style: none; }
.footer-col ul li { margin-bottom: 0.75rem; }
.footer-col ul li a {
  font-family: 'Inter', sans-serif;
  font-size: 0.9rem;
  color: rgba(255,255,255,0.5);
  transition: color 0.2s;
}
.footer-col ul li a:hover { color: #fff; }
.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 2rem;
  border-top: 1px solid rgba(255,255,255,0.08);
  flex-wrap: wrap;
  gap: 1rem;
}
.footer-bottom p {
  font-family: 'Inter', sans-serif;
  font-size: 0.8rem;
  color: rgba(255,255,255,0.3);
}
.footer-legal {
  display: flex;
  gap: 1.5rem;
}
.footer-legal a {
  font-family: 'Inter', sans-serif;
  font-size: 0.8rem;
  color: rgba(255,255,255,0.3);
  transition: color 0.2s;
}
.footer-legal a:hover { color: #fff; }

/* ===== COUNTRY SELECTOR ===== */
.country-selector-wrapper { position: relative; }
.country-selector-btn {
  background: rgba(255,255,255,0.05);
  border: 1px solid rgba(255,255,255,0.15);
  color: rgba(255,255,255,0.7);
  font-family: 'Inter', sans-serif;
  font-size: 0.85rem;
  padding: 0.5rem 1rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  transition: background 0.2s, border-color 0.2s;
  white-space: nowrap;
}
.country-selector-btn:hover { background: rgba(255,255,255,0.1); border-color: rgba(255,255,255,0.3); }
.country-dropdown {
  position: absolute;
  bottom: 100%;
  left: 0;
  margin-bottom: 0.5rem;
  background: #1a1a1a;
  border: 1px solid rgba(255,255,255,0.1);
  min-width: 200px;
  z-index: 100;
  box-shadow: 0 -8px 30px rgba(0,0,0,0.5);
}
.country-option {
  display: block;
  padding: 0.65rem 1rem;
  font-family: 'Inter', sans-serif;
  font-size: 0.85rem;
  color: rgba(255,255,255,0.65);
  transition: background 0.15s, color 0.15s;
}
.country-option:hover { background: rgba(255,0,0,0.1); color: #fff; }
.country-option.active { color: #FF0000; }

/* ===== NEWSLETTER (shared) ===== */
.newsletter {
  background: #1a1a1a;
  padding: 5rem 2rem;
  text-align: center;
}
.newsletter h2 {
  font-family: 'Oswald', sans-serif;
  font-size: clamp(1.8rem, 3vw, 2.5rem);
  font-weight: 700;
  text-transform: uppercase;
  color: #fff;
  margin-bottom: 0.75rem;
}
.newsletter p {
  font-family: 'Inter', sans-serif;
  color: rgba(255,255,255,0.55);
  margin-bottom: 2rem;
  font-size: 1rem;
}
.newsletter-form {
  display: flex;
  max-width: 480px;
  margin: 0 auto;
}
.newsletter-form input[type="email"] {
  flex: 1;
  background: #111;
  border: 1px solid #333;
  border-right: none;
  color: #fff;
  font-family: 'Inter', sans-serif;
  font-size: 0.95rem;
  padding: 0.85rem 1.25rem;
  outline: none;
  transition: border-color 0.2s;
}
.newsletter-form input[type="email"]:focus { border-color: #FF0000; }
.newsletter-form input[type="email"].error { border-color: #ff4444; }
.newsletter-form button {
  background: #FF0000;
  color: #fff;
  border: none;
  font-family: 'Oswald', sans-serif;
  font-weight: 600;
  font-size: 0.9rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 0.85rem 1.75rem;
  cursor: pointer;
  transition: background 0.2s;
}
.newsletter-form button:hover { background: #cc0000; }
.newsletter-msg {
  margin-top: 0.75rem;
  font-family: 'Inter', sans-serif;
  font-size: 0.9rem;
  min-height: 1.2em;
}
.newsletter-msg.success { color: #4caf50; }
.newsletter-msg.error { color: #ff4444; }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 768px) {
  .nav-links, .nav-ctas { display: none; }
  .nav-toggle { display: flex; }
  .nav.menu-open .nav-links {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 68px;
    left: 0;
    right: 0;
    background: rgba(20,20,20,0.98);
    padding: 1rem;
    border-bottom: 1px solid rgba(255,255,255,0.06);
  }
  .nav.menu-open .nav-ctas {
    display: flex;
    position: absolute;
    top: calc(68px + var(--menu-height, 180px));
    left: 0;
    right: 0;
    padding: 1rem;
    background: rgba(20,20,20,0.98);
    border-bottom: 1px solid rgba(255,255,255,0.06);
    justify-content: center;
  }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 2rem; }
  .footer-bottom { flex-direction: column; text-align: center; }
  .newsletter-form { flex-direction: column; }
  .newsletter-form input[type="email"] { border-right: 1px solid #333; border-bottom: none; }
}
@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
}

