  <script>
    // Instructor location filter
    (function() {
      const filterBtns = document.querySelectorAll('.filter-btn');
      const cards = document.querySelectorAll('.instructor-card');
      const countEl = document.getElementById('filterCount');
      const noResults = document.getElementById('noResults');

      function updateCount(visible, location) {
        const loc = location === 'all' ? 'all' : location;
        if (loc === 'all') {
          countEl.textContent = `Showing all ${visible} instructors`;
        } else {
          countEl.textContent = `Showing ${visible} instructor${visible !== 1 ? 's' : ''} in ${location}`;
        }
        noResults.classList.toggle('visible', visible === 0);
      }

      filterBtns.forEach(btn => {
        btn.addEventListener('click', () => {
          filterBtns.forEach(b => b.classList.remove('active'));
          btn.classList.add('active');
          const location = btn.dataset.location;
          let visible = 0;
          cards.forEach(card => {
            const match = location === 'all' || card.dataset.location === location;
            card.classList.toggle('hidden', !match);
            if (match) visible++;
          });
          updateCount(visible, location);
        });
      });
    })();

    initNewsletter('newsletterForm', 'newsletterEmail', 'newsletterMsg');
  </script>
